# Compiles the light-list mask rebuild shader into src/gfx/nvn/earlyz_mask_shaders.inc (uint32 arrays).
# The .inc is committed, so building the runtime does not need the SDK. Run: python -I scripts/gen_earlyz_mask_shaders.py
#
# Why it exists (HANDOVER 45): the light list's OR shaders register a light in a 32-bit per-tile mask through a storage image.
# A fragment shader with a storage-image write makes the driver run the depth/stencil test *after* the shader, so the fragments the
# test rejects still write that mask while their colour is dropped - the mask fills with lights the list never got, bitCount reaches
# four and every later light of that tile is skipped (the black rectangle). The colour, on the other hand, IS gated by the test. So
# the mask is derived again after every list draw from the list's own flag bytes: exactly the inverse of the shader's update.
import os, shutil, struct, subprocess, tempfile

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
glslc = shutil.which("glslc") or r"C:\VulkanSDK\1.4.363.0\Bin\glslc.exe"

COMP = r"""#version 450
// t50 (RG32UI): word0 = four light-index bytes, word1 = four slot flags (0xff = the slot is written).
// t51 (R32UI): word0 = the mask of registered light bits, bit = 1 << (index & 31), as the OR shader would have built it.
layout(local_size_x = 8, local_size_y = 8) in;
layout(binding = 0, rg32ui) uniform uimage2D u_list;
layout(binding = 1, r32ui) uniform uimage2D u_mask;
layout(push_constant) uniform Push { uvec2 extent; } pc;
void main() {
    ivec2 p = ivec2(gl_GlobalInvocationID.xy);
    if (p.x >= int(pc.extent.x) || p.y >= int(pc.extent.y)) return;
    uvec2 v = imageLoad(u_list, p).xy;
    uint m = 0u;
    for (int i = 0; i < 4; ++i) {
        uint sh = uint(i * 8);
        if (((v.y >> sh) & 0xFFu) != 0u) m |= 1u << (((v.x >> sh) & 0xFFu) & 31u);
    }
    imageStore(u_mask, p, uvec4(m));
}
"""

with tempfile.TemporaryDirectory() as tmp:
    src = os.path.join(tmp, "earlyz_mask.comp")
    with open(src, "w", newline="\n") as f:
        f.write(COMP)
    spv = subprocess.run([glslc, "-O", "--target-env=vulkan1.3", "-o", "-", "-fshader-stage=comp", src],
                         capture_output=True, check=True).stdout
words = struct.unpack("<%dI" % (len(spv) // 4), spv)

out = ["// GENERATED by scripts/gen_earlyz_mask_shaders.py from the GLSL in that script: do not edit\n",
       "static const uint32_t kEarlyzMaskComp[] = {\n"]
for i in range(0, len(words), 8):
    out.append("    " + ", ".join("0x%08x" % w for w in words[i:i + 8]) + ",\n")
out.append("};\n")

dest = os.path.join(root, "src", "gfx", "nvn", "earlyz_mask_shaders.inc")
with open(dest, "w", newline="\n") as f:
    f.write("".join(out))
print("wrote %s (%d words)" % (dest, len(words)))